mapper.select:
SELECT `id` as id, `name` as name FROM `chart_account_groups` WHERE `is_active` IN (0, 1)
AND chart_account_type_id = #{filter.accountTypeId}
AND name LIKE CONCAT("%", #{filter.searchText}, "%") ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name FROM `provinces` WHERE `is_active` = 1
AND `name` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name FROM `module_types` WHERE `status` = 1
AND `name` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as nameEn, name_kh AS nameKh, employee_code AS code FROM `employees` WHERE `is_active` = 1
AND (`name` LIKE CONCAT("%", #{filter.searchText}, "%") OR `name_kh` LIKE CONCAT("%", #{filter.searchText}, "%"))
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as nameEn, work_telephone AS nameKh, vendor_code AS code FROM `vendors` WHERE `is_active` = 1
AND `name` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `so_code` as name, (total_amount + total_vat) AS amount FROM `sales_orders` WHERE balance > 0 AND id NOT IN ( SELECT sales_order_id FROM ar_schedule_details WHERE is_active = 1 )
AND `so_code` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `po_code` as name, balance AS amount FROM `purchase_orders` WHERE balance > 0 AND status > 0 AND id NOT IN ( SELECT purchase_order_id FROM ap_schedule_details WHERE is_active = 1 )
AND `po_code` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name FROM `locations` WHERE 1
AND `name` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT products.id as id, hr_fix_asset_groups.id as fixAssetGroupId, hr_fix_asset_groups.name as fixAssetGroupName, products.code as code, products.barcode as barcode, products.name as name, uoms.id as uomId, uoms.name as uomName, products.spec as spec, products.note as model FROM products LEFT JOIN hr_fix_asset_groups ON hr_fix_asset_groups.id = products.hr_fix_asset_group_id LEFT JOIN uoms ON uoms.id = products.price_uom_id WHERE products.is_active = 8
AND products.name LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY products.id ASC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `name` as name FROM `cgroups` WHERE 1
AND `name` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id DESC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT `id` as id, `contact_name` as name FROM `customer_contacts` WHERE customer_id = #{filter.customerId}
AND `name` LIKE CONCAT("%", #{filter.searchText}, "%")
ORDER BY id DESC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT purchase_requests.id AS id, IFNULL((purchase_requests.total_amount + purchase_requests.total_vat), 0) AS balance, purchase_requests.pr_code AS code, 1 AS applyToType, purchase_requests.vendor_id AS applyToId, (SELECT CONCAT(vendor_code , '-', name) FROM vendors WHERE id = purchase_requests.vendor_id) AS applyToName FROM purchase_requests WHERE purchase_requests.is_close = 0 AND purchase_requests.status > 0 AND (purchase_requests.total_amount + purchase_requests.total_vat) > IFNULL(purchase_requests.total_deposit,0)
AND purchase_requests.company_id = #{filter.companyId}
ORDER BY id DESC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT id AS id, IFNULL(balance, 0) AS balance, po_code AS code, 1 AS applyToType, purchase_orders.vendor_id AS applyToId, (SELECT CONCAT(vendor_code , '-', name) FROM vendors WHERE id = purchase_orders.vendor_id) AS applyToName FROM purchase_orders WHERE status > 0 AND purchase_orders.balance > 0
AND purchase_orders.company_id = #{filter.companyId}
ORDER BY id DESC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT id AS id, IFNULL(((quotations.total_amount - IFNULL(quotations.discount, 0)) + quotations.total_vat), 0) AS balance, quotation_code AS code, 2 AS applyToType, customer_id AS applyToId, (SELECT CONCAT(customer_code , '-', name) FROM customers WHERE id = quotations.customer_id) AS applyToName FROM quotations WHERE status > 0 AND is_close = 0 AND ((quotations.total_amount - IFNULL(quotations.discount, 0)) + quotations.total_vat) > IFNULL(quotations.total_deposit, 0)
AND quotations.company_id = #{filter.companyId}
ORDER BY id DESC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT id AS id, IFNULL(balance, 0) AS balance, so_code AS code, 2 AS applyToType, customer_id AS applyToId, (SELECT CONCAT(customer_code , '-', name) FROM customers WHERE id = sales_orders.customer_id) AS applyToName FROM sales_orders WHERE status > 0 AND balance > 0
AND company_id = #{filter.companyId}
ORDER BY id DESC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT id AS id, LAST_DAY(date) AS name FROM reconciles WHERE company_id= 1 AND is_active = 1
AND chart_account_id = #{filter.chartAccountId}
ORDER BY created DESC LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT
    COUNT(id)
FROM reconciles
WHERE company_id= 1 AND is_active = 1

    AND chart_account_id = #{filter.chartAccountId}


    AND branch_id = #{filter.branchId}
